#!/usr/bin/env python3
"""Regenerate the package-owned file inventory used by install.sh.

Run this against an extracted release directory, never against ~/.codex. The shell
installer enforces that distinction before invoking this helper automatically.
"""
from __future__ import annotations

import argparse
import os
from pathlib import Path
import sys

MANIFEST_NAME = "DISTRIBUTION-MANIFEST.txt"
HEADER = (
    "# Generated by tools/update_distribution_manifest.py; do not edit by hand.\n"
    "# Package-owned files only; user state and build artifacts are excluded.\n"
)
EXCLUDED_DIRS = {
    ".git",
    ".venv",
    "venv",
    "node_modules",
    "__pycache__",
    ".pytest_cache",
    ".mypy_cache",
    ".ruff_cache",
    "dist",
    "build",
}
EXCLUDED_NAMES = {
    ".DS_Store",
    "config.toml",
    "secrets.toml",
    ".env",
    ".env.local",
    ".env.production",
}
EXCLUDED_SUFFIXES = {".pyc", ".pyo", ".zip", ".sha256", ".pem", ".key", ".p12", ".pfx"}


def should_exclude(relative: Path) -> bool:
    if any(part in EXCLUDED_DIRS for part in relative.parts):
        return True
    if any(part.startswith(".") for part in relative.parts):
        return True
    name = relative.name
    if name in EXCLUDED_NAMES or name.endswith((".bak", ".tmp", "~")):
        return True
    if relative.suffix.lower() in EXCLUDED_SUFFIXES:
        return True
    return False


def build_manifest(root: Path) -> str:
    entries: set[str] = {MANIFEST_NAME}
    for path in root.rglob("*"):
        if not path.is_file() or path.is_symlink():
            continue
        relative = path.relative_to(root)
        if relative.as_posix() == MANIFEST_NAME or should_exclude(relative):
            continue
        entries.add(relative.as_posix())
    return HEADER + "\n".join(sorted(entries)) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", nargs="?", type=Path, help="extracted release directory (defaults to this package root)")
    parser.add_argument("--check", action="store_true", help="fail instead of writing when the manifest is stale")
    args = parser.parse_args()

    root = (args.root or Path(__file__).resolve().parent.parent).expanduser().resolve()
    if not root.is_dir():
        parser.error(f"not a directory: {root}")
    manifest = root / MANIFEST_NAME
    expected = build_manifest(root)
    current = manifest.read_text(encoding="utf-8") if manifest.is_file() else None
    if current == expected:
        print(f"Distribution manifest is up to date ({len(expected.splitlines()) - 2} files): {manifest}")
        return 0
    if args.check:
        print(f"Distribution manifest is stale: {manifest}", file=sys.stderr)
        return 1

    temp = manifest.with_name(f"{manifest.name}.tmp-{os.getpid()}")
    try:
        temp.write_text(expected, encoding="utf-8", newline="\n")
        temp.replace(manifest)
    finally:
        if temp.exists():
            temp.unlink()
    print(f"Updated distribution manifest ({len(expected.splitlines()) - 2} files): {manifest}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
